export function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < x.length && i < y.length; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

export function toJson(root) {
  const go = (n, ind) => {
    const pad = '  '.repeat(ind + 1)
    const end = '  '.repeat(ind)
    if (n.type === 'table') {
      const ks = sortedKeys(n)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${go(n.map.get(k), ind + 1)}`).join(',\n') + `\n${end}}`
    }
    if (n.type === 'array') {
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((v) => pad + go(v, ind + 1)).join(',\n') + `\n${end}]`
    }
    return JSON.stringify(n.value)
  }
  return go(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const go = (n, path) => {
    if (n.type === 'table') {
      for (const k of sortedKeys(n)) visit(n.map.get(k), path === null ? k : `${path}.${k}`)
    } else {
      n.items.forEach((v, i) => visit(v, `${path}[${i}]`))
    }
  }
  const visit = (n, path) => {
    lines.push(`${path} ${n.type}`)
    if (n.type === 'table' || n.type === 'array') go(n, path)
  }
  go(root, null)
  return lines.map((l) => l + '\n').join('')
}
