export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const table = () => ({ type: 'table', map: new Map(), header: false })
const BARE = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const isComment = (c) => c === '#' || c === ';'
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

