    const s = lines[n]
    let i = 0
    const fail = (m) => { throw new ParseError(n + 1, m) }
    const ws = () => { while (i < s.length && isWs(s[i])) i++ }
    const atEnd = () => i >= s.length || isComment(s[i])

    const str = () => {
      const q = s[i++]
      let r = ''
      for (;;) {
        if (i >= s.length) fail('unterminated string')
        const c = s[i++]
        if (c === q) return r
        if (q === '"' && c === '\\') {
          if (i >= s.length) fail('unterminated string')
          const e = s[i++]
          const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
          if (e in map) r += map[e]
          else if (e === 'u') {
            const h = s.slice(i, i + 4)
            if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
            r += String.fromCharCode(parseInt(h, 16))
            i += 4
          } else fail(`invalid escape \\${e}`)
        } else r += c
      }
    }

    const name = () => {
      ws()
      const c = s[i]
      if (c === '"' || c === "'") return str()
      const st = i
      while (i < s.length && BARE.test(s[i])) i++
      if (i === st) fail('expected a name')
      return s.slice(st, i)
    }
    const dotted = () => {
      const names = [name()]
      for (;;) {
        ws()
        if (s[i] !== '.') return names
        i++
        names.push(name())
      }
    }

    // Walk intermediate names, creating implicit tables. Returns the table.
    const walk = (t, names, base) => {
      let path = base
      for (const k of names) {
        path = path === null ? k : `${path}.${k}`
        let c = t.map.get(k)
        if (!c) { c = table(); t.map.set(k, c) }
