    const assign = (t, base, names, value) => {
      const parent = walk(t, names.slice(0, -1), base)
      const k = names[names.length - 1]
      if (parent.map.has(k)) fail(`key ${join(base, names)} is defined twice`)
      parent.map.set(k, value)
    }

    const value = (path, ctx) => {
      ws()
      if (atEnd() || s[i] === ',' || s[i] === ']' || s[i] === '}') fail('expected a value')
      const c = s[i]
      if (c === '"' || c === "'") return { type: 'string', value: str() }
      if (c === '[') {
        i++
        const arr = { type: 'array', items: [], aot: false }
        for (;;) {
          ws()
          if (atEnd()) fail('unterminated array')
          if (s[i] === ']' && arr.items.length) { i++; return arr }
          if (s[i] === ']') { i++; return arr }
          arr.items.push(value(`${path}[${arr.items.length}]`))
