      ws()
      if (!atEnd()) fail('trailing text after a table header')
      const parent = walk(root, names.slice(0, -1), null)
      const k = names[names.length - 1]
      const path = names.join('.')
      const ex = parent.map.get(k)
      if (aot) {
        const fresh = table()
        if (!ex) parent.map.set(k, { type: 'array', items: [fresh], aot: true })
        else if (ex.type === 'array' && ex.aot) ex.items.push(fresh)
        else fail(`${path} is not an array of tables`)
        current = fresh
      } else {
        if (!ex) {
          const t = table()
          t.header = true
          parent.map.set(k, t)
          current = t
        } else if (ex.type !== 'table') fail(`${path} is not a table`)
        else {
          if (ex.header) fail(`table ${path} is defined twice`)
          ex.header = true
          current = ex
        }
      }
      continue
    }

    const names = dotted()
    ws()
    if (s[i] !== '=') fail('expected key = value')
    i++
    const v = value(null)
    ws()
    if (!atEnd()) fail('trailing text after a value')
    // path from root: the current table's path is unknown here, so track it.
    assignFrom(current, names, v)

    function assignFrom(t, ns, val) {
      const parent = walk(t, ns.slice(0, -1), pathOf(t))
      const k = ns[ns.length - 1]
      if (parent.map.has(k)) fail(`key ${join(pathOf(t), ns)} is defined twice`)
      parent.map.set(k, val)
    }
  }
  return root

  function pathOf(t) {
    return paths.get(t) ?? null
  }
}
